
.npc-profile {
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.npc-profile__nav {
  display: flex;
  align-items: center;
  gap: 10px;
}

.npc-profile__back {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 10px 6px 8px;
  border: none;
  border-radius: var(--gal-radius-pill);
  background: rgba(255, 255, 255, 0.06);
  color: var(--gal-text-muted);
  font-size: 12px;
  cursor: pointer;
  transition:
    color 0.15s ease,
    background 0.15s ease;

  &:hover {
    color: var(--gal-text);
    background: rgba(255, 255, 255, 0.1);
  }
}

.npc-profile__nav-label {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gal-text-muted);
  opacity: 0.85;
}

.npc-profile__hero {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

.npc-profile__portrait {
  flex-shrink: 0;
  padding: 3px;
  border-radius: 50%;
  background: var(--gal-gradient-primary);
  box-shadow: 0 0 20px rgba(244, 114, 182, 0.2);
}

.npc-profile__avatar-fallback {
  width: 88px;
  height: 88px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  font-weight: 700;
  color: var(--gal-pink);
  background: var(--gal-panel-light);
}

.npc-profile__identity {
  flex: 1;
  min-width: 0;
}

.npc-profile__name {
  margin: 0 0 10px;
  font-size: 18px;
  font-weight: 800;
  color: var(--gal-text);
  line-height: 1.2;
  word-break: break-word;
}

.npc-profile__meta {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.npc-profile__meta-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--gal-border);

  span {
    color: var(--gal-text-muted);
    flex-shrink: 0;
  }

  strong {
    text-align: right;
    word-break: break-word;
  }
}

.npc-profile__level {
  color: var(--gal-blue);
}

.npc-profile__bonds {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.bond-card {
  padding: 12px 12px 10px;
}

.bond-card__head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
  font-size: 11px;
  color: var(--gal-text-muted);

  i {
    font-size: 13px;
    color: var(--gal-pink);
  }

  strong {
    margin-left: auto;
    font-size: 18px;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
    color: var(--gal-text);
  }
}

.bond-card__bar {
  height: 5px;
  border-radius: var(--gal-radius-pill);
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.bond-card__fill {
  height: 100%;
  border-radius: inherit;
  transition: width 0.35s ease;

  &--heart {
    background: linear-gradient(90deg, #fb7185, #f472b6);
  }

  &--lust {
    background: linear-gradient(90deg, #f97316, #fb7185);
  }
}

.npc-profile__stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.stat-card {
  text-align: center;
  padding: 14px 10px;

  i {
    display: block;
    font-size: 18px;
    margin-bottom: 6px;
    color: var(--gal-violet);
  }
}

.stat-card__label {
  display: block;
  font-size: 10px;
  color: var(--gal-text-muted);
  letter-spacing: 0.06em;
}

.stat-card__value {
  font-size: 20px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.npc-profile__thought {
  padding: 12px 14px;
}

.npc-profile__thought-label {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
  font-size: 10px;
  letter-spacing: 0.08em;
  color: var(--gal-violet);
  font-weight: 700;

  i {
    font-size: 11px;
    opacity: 0.9;
  }
}

.npc-profile__thought p {
  margin: 0;
  font-size: 12px;
  line-height: 1.6;
  color: var(--gal-text-muted);
  font-style: italic;
}
