
.map-panel {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  overflow-y: auto;
}

.map-panel__here {
  margin: 0;
  padding: 8px 10px;
  font-size: 12px;
  color: var(--gal-text-muted);
  border-radius: var(--gal-radius-sm);
  background: rgba(56, 189, 248, 0.08);
  border: 1px solid rgba(56, 189, 248, 0.2);

  i {
    margin-right: 6px;
    color: var(--gal-blue);
  }

  strong {
    color: var(--gal-text);
  }
}

.region-card__head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;

  strong {
    font-size: 15px;
  }
}

.region-card__boss {
  margin: 0 0 6px;
  font-size: 11px;
  color: var(--gal-pink);

  i {
    margin-right: 4px;
    font-size: 10px;
  }
}

.region-card__desc {
  font-size: 12px;
  color: var(--gal-text-muted);
  line-height: 1.5;
  margin: 0 0 8px;
}

.region-card__areas {
  margin-bottom: 8px;
}

.region-card__areas-label {
  display: block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--gal-blue);
  margin-bottom: 4px;
}

.region-card__areas-list {
  margin: 0;
  padding-left: 16px;
  font-size: 11px;
  line-height: 1.45;
  color: var(--gal-text);

  li {
    margin-bottom: 2px;
  }
}

.region-card__area-btn {
  padding: 0;
  border: none;
  background: none;
  font: inherit;
  font-size: 11px;
  color: var(--gal-text);
  cursor: pointer;
  text-align: left;
  text-decoration: underline dotted rgba(56, 189, 248, 0.45);
  text-underline-offset: 2px;

  &:hover {
    color: var(--gal-blue);
  }
}

.region-card__hook {
  margin: 0 0 10px;
  padding: 6px 8px;
  font-size: 10px;
  line-height: 1.4;
  color: var(--gal-violet);
  border-radius: var(--gal-radius-sm);
  background: rgba(139, 92, 246, 0.1);
  border: 1px dashed rgba(139, 92, 246, 0.25);

  i {
    margin-right: 4px;
    font-size: 9px;
  }
}

.region-card__actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.region-card__btn {
  width: 100%;

  &--here {
    opacity: 0.72;
    cursor: not-allowed;
    border-color: rgba(56, 189, 248, 0.35);
    background: rgba(56, 189, 248, 0.12);
    color: var(--gal-blue);
  }

  &--wild {
    border-color: rgba(251, 113, 133, 0.35);
    color: var(--gal-pink);
  }
}
