
.npc-panel {
  min-height: 0;
  overflow-y: auto;
}

.npc-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.npc-card__header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 12px;
}

.npc-card__avatar-btn {
  flex-shrink: 0;
  padding: 0;
  border: none;
  background: transparent;
  cursor: pointer;
  border-radius: 50%;
  transition: transform 0.15s ease, filter 0.15s ease;

  &:hover {
    transform: scale(1.04);
    filter: brightness(1.08);
  }

  &:active {
    transform: scale(0.98);
  }
}

.npc-card__avatar-fallback {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  color: var(--gal-pink);
  background: var(--gal-panel-light);
  box-shadow: inset 0 0 0 2px rgba(96, 165, 250, 0.55);
  pointer-events: none;
}

.npc-card__title {
  flex: 1;
  min-width: 0;

  strong {
    display: block;
    font-size: 16px;
    margin-bottom: 2px;
  }

  span {
    color: var(--gal-text-muted);
    font-size: 11px;
    line-height: 1.4;
  }
}

.npc-card__chat {
  border: none;
  background: var(--gal-gradient-primary);
  color: #fff;
  box-shadow: var(--gal-shadow-glow);
}

.npc-card__stats,
.npc-card__abilities {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 8px;
  font-size: 11px;
  color: var(--gal-text-muted);

  i {
    margin-right: 3px;
    color: var(--gal-pink);
  }
}

.npc-card__abilities i {
  color: var(--gal-blue);
}

.npc-card__thought {
  margin: 0;
  line-height: 1.5;
  font-size: 11px;
  color: var(--gal-text-muted);

  strong {
    display: block;
    font-size: 10px;
    letter-spacing: 0.08em;
    color: var(--gal-violet);
    margin-bottom: 2px;
  }
}
