
.npc-status {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid var(--gal-border);

  &--embedded {
    margin-top: 0;
    padding-top: 0;
    border-top: none;
  }
}

.npc-status__block {
  padding: 10px 12px;
  border-radius: var(--gal-radius-sm);
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.npc-status__heading {
  margin: 0 0 6px;
  font-size: 12px;
  font-weight: 700;
  color: var(--gal-text);
  letter-spacing: 0.02em;
}

.npc-status__rows {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.npc-status__row {
  margin: 0;
  font-size: 11px;
  line-height: 1.45;
  color: var(--gal-text-muted);
  word-break: break-word;
}

.npc-status__prefix {
  margin-right: 2px;
}

.npc-status__label {
  color: var(--gal-text);
  margin-right: 4px;
}

.npc-status__value {
  color: var(--gal-text-muted);
}

.npc-status__list {
  margin: 4px 0 0;
  padding-left: 18px;
  font-size: 11px;
  line-height: 1.5;
  color: var(--gal-text-muted);

  li {
    margin-bottom: 4px;
  }
}

.npc-status__legacy {
  margin: 0;
  font-size: 11px;
  line-height: 1.5;
  color: var(--gal-text-muted);

  strong {
    display: block;
    font-size: 10px;
    letter-spacing: 0.08em;
    color: var(--gal-text);
    margin-bottom: 2px;
  }
}
