
.battle-arena {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10px 12px 12px;
  border-radius: var(--gal-radius-md);
  overflow: hidden;
  cursor: default;
  user-select: none;

  &--ready {
    cursor: pointer;
  }
}

.battle-arena__backdrop {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 20% 30%, rgba(59, 130, 246, 0.22) 0%, transparent 42%),
    radial-gradient(circle at 80% 70%, rgba(244, 114, 182, 0.2) 0%, transparent 45%),
    linear-gradient(165deg, rgba(8, 12, 26, 0.94) 0%, rgba(26, 16, 48, 0.9) 100%);
  backdrop-filter: blur(8px);
}

.battle-arena__spark {
  position: absolute;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(252, 211, 77, 0.85);
  box-shadow: 0 0 10px rgba(252, 211, 77, 0.6);
  animation: spark-twinkle 2.4s ease-in-out infinite;
  opacity: 0.55;
}

.battle-arena__label {
  position: relative;
  z-index: 1;
  margin: 0 0 6px;
  font-size: 10px;
  letter-spacing: 0.14em;
  font-weight: 700;
  color: rgba(226, 232, 240, 0.55);
}

.battle-arena__field {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 320px;
  min-height: 108px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
  padding: 0 4px;
}

.battle-arena__slot {
  flex: 1;
  display: flex;
  justify-content: center;
  will-change: transform;

  &--player {
    justify-content: flex-start;
  }

  &--enemy {
    justify-content: flex-end;
  }
}

.battle-arena__vs {
  position: absolute;
  left: 50%;
  top: 46%;
  transform: translate(-50%, -50%) scale(0.85);
  opacity: 0.75;
  pointer-events: none;

  &-text {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 36px;
    height: 36px;
    padding: 0 8px;
    border-radius: 50%;
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.08em;
    color: var(--gal-gold);
    background: rgba(8, 12, 24, 0.72);
    border: 1px solid rgba(252, 211, 77, 0.45);
    box-shadow: 0 0 18px rgba(252, 211, 77, 0.25);
  }
}

.battle-arena--fighting .battle-arena__vs {
  opacity: 0.35;
}

.battle-arena__speech {
  position: relative;
  z-index: 1;
  margin: 8px 0 0;
  max-width: 92%;
  padding: 8px 12px;
  border-radius: var(--gal-radius-md);
  font-size: 11px;
  line-height: 1.45;
  color: #f1f5f9;
  text-align: center;
  background: rgba(8, 12, 24, 0.72);
  border: 1px solid rgba(244, 114, 182, 0.35);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.25);
}

.battle-arena__hint {
  position: relative;
  z-index: 1;
  margin: 8px 0 0;
  font-size: 11px;
  color: var(--gal-blue);

  &--muted {
    color: var(--gal-text-muted);
  }

  &--encounter {
    color: var(--gal-gold);
    animation: hint-pulse 1.6s ease-in-out infinite;
  }
}

.battle-arena--ready .battle-arena__hint:not(.battle-arena__hint--encounter) {
  animation: hint-pulse 1.6s ease-in-out infinite;
}

.battle-arena__damage {
  position: absolute;
  z-index: 6;
  top: 38%;
  font-size: 24px;
  font-weight: 800;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.6);
  pointer-events: none;

  &--player {
    right: 20%;
    color: var(--gal-gold);
  }

  &--enemy {
    left: 20%;
    color: var(--gal-danger);
  }
}

.damage-pop-enter-active,
.damage-pop-leave-active {
  transition:
    opacity 0.25s ease,
    transform 0.45s ease;
}

.damage-pop-enter-from,
.damage-pop-leave-to {
  opacity: 0;
  transform: translateY(8px) scale(0.85);
}

@keyframes spark-twinkle {
  0%,
  100% {
    opacity: 0.25;
    transform: scale(0.8);
  }

  50% {
    opacity: 1;
    transform: scale(1.2);
  }
}

@keyframes hint-pulse {
  0%,
  100% {
    opacity: 0.65;
  }

  50% {
    opacity: 1;
  }
}
